import{_ as a,o as s,c as t,a3 as o}from"./chunks/framework.enEKIwRN.js";const g=JSON.parse('{"title":"Use cicada from an agent","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/use-from-an-agent.md","filePath":"how-to/use-from-an-agent.md"}'),n={name:"how-to/use-from-an-agent.md"};function i(d,e,c,r,l,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="use-cicada-from-an-agent" tabindex="-1">Use cicada from an agent <a class="header-anchor" href="#use-cicada-from-an-agent" aria-label="Permalink to &quot;Use cicada from an agent&quot;">​</a></h1><p>This guide shows you how to expose cicada to an MCP-capable agent so it can read, plan, and reconcile calendars through the same engine the CLI drives — with every mutation gated by the planDigest contract.</p><h2 id="the-server" tabindex="-1">The server <a class="header-anchor" href="#the-server" aria-label="Permalink to &quot;The server&quot;">​</a></h2><p>There is no <code>cicada-mcp</code> binary (deleted in T-019): the MCP surface is <code>tamias-driver-cicada mcp</code>, installed by <code>cargo xtask install</code> alongside the driver. It speaks MCP over <strong>stdio</strong> and renders the engine ops manifest as tools — one tool per bounded verb (<code>plan</code>, <code>apply</code>, <code>drift</code>, <code>range</code>, …), params are the verb&#39;s own flags.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;cicada&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tamias-driver-cicada&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Ops inherit the server process&#39;s <strong>cwd</strong> — <code>cicada.yaml</code> manifest discovery, <code>.cicada/</code> state, and <code>CICADA_*</code> env apply exactly as for the <code>cicada</code> binary. Launch the server with the project root as its working directory (most MCP clients support a <code>cwd</code> field), or pass calendar file paths via each tool&#39;s <code>files</code> argument.</p><p>Per-call provider selection rides the <code>provider</code> param (<code>fake</code>/<code>google</code>); <code>fake_file</code>, <code>state</code>, and the <code>CICADA_*</code> env vars work the same as on the CLI. <code>provider.add</code> is deliberately <strong>not</strong> a tool — the OAuth flow needs stdin/browser, so it stays an interactive surface (<code>cicada provider add google</code>, see <a href="./connect-google.html">Connect Google Calendar</a>).</p><h2 id="the-tool-surface" tabindex="-1">The tool surface <a class="header-anchor" href="#the-tool-surface" aria-label="Permalink to &quot;The tool surface&quot;">​</a></h2><p>Reads are always safe — <code>list</code>, <code>range</code>, <code>show</code>, <code>drift</code>, <code>validate</code> only read. Mutating verbs are <code>init</code> (scaffolds files), <code>plan</code> (can write <code>--out</code>), <code>apply</code>, <code>refresh</code>, <code>fmt</code>. There is <strong>no <code>events.create</code></strong>: desired state lives in YAML — to add an event the agent edits the calendar file, plans, and applies. See the <a href="./../reference/mcp-tools.html">MCP tools reference</a>.</p><h2 id="the-write-contract" tabindex="-1">The write contract <a class="header-anchor" href="#the-write-contract" aria-label="Permalink to &quot;The write contract&quot;">​</a></h2><p><code>apply</code> is gated — mutations are never implicit:</p><ol><li><code>plan</code> prints a <code>planDigest</code> (<code>sha256:…</code>), persisted beside the state file — issued digests survive process boundaries.</li><li><code>apply --plan-digest &lt;digest&gt;</code> must name an issued, unspent digest; the engine re-plans and refuses if YAML, live, or recorded state drifted since the preview. Digests are single-use.</li><li>Without <code>--plan-digest</code>, <code>apply</code> falls back to the interactive confirmation prompt — under MCP (null stdin) that fails closed and aborts, so agents must go through the digest path. <code>--auto-approve</code> exists for CI but is the caller&#39;s explicit choice, not a default.</li></ol><p>Typical agent flow:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. list                              → see declared calendars</span></span>
<span class="line"><span>2. range {from, to}                  → find a gap</span></span>
<span class="line"><span>3. (edit calendars/*.yaml)           → declare the event</span></span>
<span class="line"><span>4. plan                              → read planDigest + the diff,</span></span>
<span class="line"><span>                                        show the user the plan</span></span>
<span class="line"><span>5. apply {planDigest, autoApprove?}  → user approved</span></span></code></pre></div><p>Errors carry a class — <code>transient</code> (retry), <code>conflict</code> (refresh + re-plan), <code>auth</code> (surface the token flow), <code>fatal</code> (fix the input) — so the agent knows whether to retry or ask a human.</p>`,15)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
